fn determine_food_safety(x: i8, a: i8, b: i8) -> &'static str {
    // Compute the difference in a wider type to avoid overflow
    let days_past = b as i16 - a as i16;
    if days_past <= 0 {
        "delicious"
    } else if days_past <= x as i16 {
        "safe"
    } else {
        "dangerous"
    }
}

