        assert_eq!(determine_food_safety(5, 10, 10), "delicious");
        assert_eq!(determine_food_safety(5, 10, 9), "delicious");

        // 0 < days_past <= x → "safe"
        assert_eq!(determine_food_safety(3, 10, 11), "safe");
        assert_eq!(determine_food_safety(3, 10, 13), "safe");

        // days_past > x → "dangerous"
        assert_eq!(determine_food_safety(3, 10, 14), "dangerous");

        // edge: x = 0
        assert_eq!(determine_food_safety(0, 5, 5), "delicious");
        assert_eq!(determine_food_safety(0, 5, 6), "dangerous");
